for (const kind of ['schedules','batches']) test(kind+'创建丢回包及迟到同内容旧计划不认作本意图，刷新后只恢复原key', {skip:!browser},async()=>run(String.raw`
 const kind='${kind}';let postCount=0,realCreated=0,stored=[],firstList=true;const originalFetch=window.fetch;
 window.fetch=async(url,options={})=>{if(String(url).endsWith('/'+kind)){window.calls.push({url:String(url),method:options.method||'GET',body:options.body?JSON.parse(options.body):{}});const method=options.method||'GET';if(method==='GET'&&firstList){firstList=false;return new Promise(r=>{window.releaseOld=()=>r(response({[kind]:[{...window.originalCreate,id:'identical-old',status:'stopped',completedChapters:0}]}))})}if(method==='GET')return response({[kind]:stored});const body=JSON.parse(options.body);postCount++;let found=body.idempotencyKey&&stored.find(p=>p.creation?.idempotencyKey===body.idempotencyKey);if(!found){realCreated++;found={...body,id:'intent-'+realCreated,status:'stopped',completedChapters:2,creation:{idempotencyKey:body.idempotencyKey}};stored.push(found)}if(postCount===1){window.originalCreate=body;return response({error:'创建回包丢失'},504)}return response({[kind==='batches'?'batch':'schedule']:found})}return originalFetch(url,options)};
 await open();window.step='intent '+kind;type(document.querySelector('[aria-label="创作要求"]'),'与旧计划完全相同的要求');await tick();click(button(kind==='batches'?'批量续写':'定时写作'));await wait(()=>window.releaseOld);click(button(kind==='batches'?'开始批量续写':'创建定时任务'));await wait(()=>postCount===1);await tick();window.releaseOld();await tick();await tick();
 const createButton=button(kind==='batches'?'开始批量续写':'创建定时任务');if(!createButton.disabled){createButton.click();await tick();assert(realCreated===1,'迟到旧计划解锁导致第二次创建')}
 await remount();click(button(kind==='batches'?'批量续写':'定时写作'));await wait(()=>button('恢复原创建请求'));click(button('恢复原创建请求'));await wait(()=>postCount===2);assert(realCreated===1,'recovery created second plan');const posts=window.calls.filter(c=>c.url.endsWith('/'+kind)&&c.method==='POST');assert(window.originalCreate.idempotencyKey,'no stable creation key');assert(posts.length===2&&JSON.stringify(posts[0].body)===JSON.stringify(posts[1].body),'recovery changed original payload/key');assert(stored[0].status==='stopped'&&stored[0].completedChapters===2,'recovery reset progressed plan');
`, 'fix-intent-'+kind));

